private static class ParseResult {
    Set<Option> handler;
    CommandLine commandLine;
    Option opt1;
    Option opt2;
    Option opt3;
}

private ParseResult parseOptions() throws ParseException {
    Set<Option> handler = new HashSet<>();
    DefaultParser parser = DefaultParser.builder()
            .setDeprecatedHandler(handler::add)
            .build();

    Option opt1 = Option.builder().option("d1").deprecated().build();
    Option opt2 = Option.builder().option("d2")
            .deprecated(DeprecatedAttributes.builder()
                    .setForRemoval(true)
                    .setSince("1.0")
                    .setDescription("Do this instead.")
                    .get())
            .build();
    Option opt3 = Option.builder().option("a").build();

