// Helper to create a JsonWriter with indentation and its underlying StringWriter
private static WriterContext createWriter() {
  StringWriter stringWriter = new StringWriter();
  JsonWriter jsonWriter = new JsonWriter(stringWriter);
  jsonWriter.setIndent("   ");
  return new WriterContext(stringWriter, jsonWriter);
}

// Simple holder for the writer pair
private static final class WriterContext {
  final StringWriter stringWriter;
