@Test
void testReadAcrossBuffers() {
    String json = buildJsonStringAcrossBuffers();
    JsonReader reader = assertDoesNotThrow(() -> new JsonReader(reader(json)));
    reader.setStrictness(Strictness.LENIENT);
    JsonToken token = assertDoesNotThrow(reader::peek);
    assertThat(token).isEqualTo(JsonToken.NUMBER);
}

/**
 * Constructs a JSON string that spans across the internal buffer boundary of {@link JsonReader}.
 * The string consists of a leading '#', followed by enough spaces to fill the buffer up to
 * {@code JsonReader.BUFFER_SIZE - 3}, then the JSON prefix {@code "\n)]}'\n"} and finally the
 * number {@code "3"}.
 *
 * @return the constructed JSON string.
 */
private String buildJsonStringAcrossBuffers() {
    StringBuilder sb = new StringBuilder("#");
    for (int i = 0; i < JsonReader.BUFFER_SIZE - 3; i++) {
        sb.append(' ');
    }
    sb.append("\n)]}'\n3");
    return sb.toString();
}

