public void escapesGtInXmlAttributesButNotInHtml() {
    // https://github.com/jhy/jsoup/issues/528 - < is OK in HTML attribute values, but not in XML
    String docHtml = "<a title='<p>One</p>'>One</a>";
    Document doc = Jsoup.parse(docHtml);
    Element element = doc.select("a").first();

    doc.outputSettings().escapeMode(base);
    assertEquals(
        "When escape mode is base, attribute values should preserve '<' characters.",
        "<a title=\"<p>One</p>\">One</a>",
        element.outerHtml()
    );

    doc.outputSettings().escapeMode(xhtml);
    assertEquals(
        "When escape mode is xhtml, '<' characters in attribute values should be escaped.",
        "<a title=\"&lt;p>One&lt;/p>\">One</a>",
        element.outerHtml()
    );
}

