    assertEquals(
        publicDoc,
        htmlOutput(publicDoc),
        "HTML output should preserve PUBLIC doctype unchanged"
    );
    assertEquals(
        publicDoc,
        xmlOutput(publicDoc),
        "XML output should preserve PUBLIC doctype unchanged"
    );

    String systemDoc = "<!DOCTYPE html SYSTEM \"exampledtdfile.dtd\">";
    assertEquals(
        systemDoc,
        htmlOutput(systemDoc),
        "HTML output should preserve SYSTEM doctype unchanged"
    );
    assertEquals(
        systemDoc,
        xmlOutput(systemDoc),
        "XML output should preserve SYSTEM doctype unchanged"
    );

    String legacyDoc = "<!DOCTYPE html SYSTEM \"about:legacy-compat\">";
    assertEquals(
        legacyDoc,
        htmlOutput(legacyDoc),
        "HTML output should preserve legacy SYSTEM doctype unchanged"
    );
    assertEquals(
        legacyDoc,
        xmlOutput(legacyDoc),
        "XML output should preserve legacy SYSTEM doctype unchanged"
    );
}

