@ParameterizedTest(name = "Iterator returns expected key \"{1}\" at position {0}")
@CsvSource({
    "0,One",
    "1,Two"
})
void testIteratorSkipsInternal_keyAtPosition(int index, String expectedKey) {
    Attributes a = createAttributes();
    Iterator<Attribute> it = a.iterator();

    for (int i = 0; i <= index; i++) {
        assertTrue(it.hasNext(),
            "Iterator should have next element at index " + i + " while expecting key \"" + expectedKey + "\"");
        Attribute attr = it.next();
        if (i == index) {
            assertEquals(expectedKey, attr.getKey(),
                "Expected key at index " + index + " to be \"" + expectedKey + "\"");
        }
    }
    assertFalse(it.hasNext(),
        "Iterator should have no more elements after processing expected keys");
}

